import sys
from support_function import *

K = 15


def main(argv=None):
    """Job entry point (design plan section 5.1, T1). Parameters: none."""
    spark = (
        SparkSession.builder.appName('recommendation_system')
        .config('spark.driver.memory', '32g')  # 32g
        .config('spark.executor.cores', '5')
        .config('spark.executor.instances', '14')
        .config('spark.executor.memory', '32g')
        .config('spark.dynamicAllocation.enabled', 'false')
        .config('spark.debug.maxToStringFields', '100')
        .config('spark.driver.memoryOverhead', '8192')
        .config('spark.executor.memoryOverhead', '8192')
        .config('spark.network.timeout', '800')
        .config('spark.yarn.queue', 'root.hdp_ds')
        .getOrCreate()
    )
    sys.path.insert(0, './recommendation_system/script/')

    today = getConfig('core', 'today')
    today = datetime.strptime(today, '%Y-%m-%d')

    queries = "SELECT * FROM {}.{} WHERE partition_date = '{}'".format('mldb', 'mii_rs_customers', today.strftime('%Y-%m-%d'))
    customers = spark.sql(queries)  # OPEN / TO BE VALIDATED: Unity Catalog names for mldb.mii_rs_customers (K7 tables, K4-TBL-004)

    exclude_col = ['cif_number', 'cif_creation_date', 'active_flag', 'flag_simobi', 'sum_idr_balance_amount', 'partition_date']

    c = 'age'
    qds = QuantileDiscretizer(numBuckets=4, inputCol=c, outputCol=c + '_group', relativeError=0.05)
    bucketizer = qds.fit(customers)
    customers = bucketizer.transform(customers)
    customers = customers.withColumn(c + '_group', F.col(c + '_group').cast('string'))
    exclude_col.append(c)

    bucketizer.write().overwrite().save('./recommendation_system/pipeline/bucketizer/age_bucketizer_{}'.format(today.strftime('%Y%m%d')))

    categorical_features = [t[0] for t in customers.dtypes if t[1] == 'string' and t[0] not in exclude_col]
    numeric_features = ['payroll_flag']

    stages = []
    for categoricalCol in categorical_features:
        stringIndexer = StringIndexer(inputCol=categoricalCol, outputCol=categoricalCol + 'Index')
        encoder = OneHotEncoder(inputCol=stringIndexer.getOutputCol(), outputCol=categoricalCol + 'ClassVec')
        stages += [stringIndexer, encoder]

    assemblerInputs = [c + 'ClassVec' for c in categorical_features] + numeric_features
    assembler = VectorAssembler(inputCols=assemblerInputs, outputCol='features')
    stages += [assembler]

    pipeline = Pipeline(stages=stages)
    pipelineModel = pipeline.fit(customers)
    train = pipelineModel.transform(customers).select('cif_number', 'features')

    pipelineModel.write().overwrite().save('./recommendation_system/pipeline/preprocessing_customer/preprocessing_customer_{}'.format(today.strftime('%Y%m%d')))
    sil_width = []
    runtimes = []
    bestModel = None
    sw0 = 0
    best_k = 0
    evaluator = ClusteringEvaluator(predictionCol="prediction")

    for k in range(3, K + 1):
        startTime = time.time()
        kmeans = KMeans().setK(k).setSeed(1).setFeaturesCol("features")
        model = kmeans.fit(train)

        transformed = model.transform(train)
        sw = evaluator.evaluate(transformed)
        sil_width.append(sw)
        runtimes.append(time.time() - startTime)
        if sw > sw0:
            sw0 = sw
            bestModel = model
            best_k = k

    clustering_summary = pd.DataFrame()
    clustering_summary['Number of Cluster'] = [k for k in range(3, K + 1)]
    clustering_summary['Silhouette Width'] = sil_width
    clustering_summary['Running Time'] = runtimes
    clustering_summary['Training Date'] = today.strftime('%Y-%m-%d')
    clustering_summary['Best K'] = ['no' if i != best_k else 'yes' for i in range(3, K + 1)]
    clustering_summary['Algorithm'] = 'k_means'
    clustering_summary.columns = [x.lower().replace(' ', '_') for x in clustering_summary.columns]
    k = clustering_summary.loc[clustering_summary['best_k'] == 'yes', 'number_of_cluster'].to_list()[0]
    clustering_summary = spark.createDataFrame(clustering_summary)
    clustering_summary = clustering_summary.withColumn('number_of_cluster', F.col('number_of_cluster').cast('int'))

    writeData(clustering_summary, spark, 'mldb', 'mii_rs_clustering_model_summary', partition='training_date')

    bestModel.write().overwrite().save('./recommendation_system/model/clustering/kmeans_{}'.format(today.strftime('%Y%m%d')))

    transformed = model.transform(train).select('cif_number', 'prediction')
    transformed = transformed.withColumnRenamed('prediction', 'cluster')
    transformed = transformed.withColumn('cluster', F.col('cluster') + 1)
    transformed = transformed.withColumn('cluster', F.concat(F.lit('cluster '), F.col('cluster')))
    transformed = transformed.repartition('cif_number')

    customers = customers.repartition('cif_number')
    transformed = transformed.join(customers[['cif_number', 'flag_simobi']], on='cif_number', how='inner')

    cluster_prob = get_summary(transformed, 'cluster')
    cluster_prob.drop(columns='percentage', inplace=True)
    cluster_prob.columns = ['cluster', 'total_customer']

    cluster_simobi = get_summary(transformed.filter(F.col('flag_simobi') == 1), 'cluster')
    cluster_simobi.drop(columns='percentage', inplace=True)
    cluster_simobi.columns = ['cluster', 'simobi_user']

    cluster_probability = cluster_prob.merge(cluster_simobi, on=['cluster'])
    cluster_probability['cluster_probability'] = round(cluster_probability['simobi_user'] / cluster_probability['total_customer'], 4) * 100

    cluster_probability['training_date'] = today.strftime('%Y-%m-%d')
    cluster_probability = spark.createDataFrame(cluster_probability)
    writeData(cluster_probability, spark, 'mldb', 'mii_rs_cluster_probability', partition='training_date')

    customer_cluster = transformed.select('cif_number', 'cluster')
    customer_cluster = customer_cluster.withColumn('predict_date', F.lit(today.strftime('%Y-%m-%d')))

    #Write to Hive/Impala
    writeData(customer_cluster, spark, 'mldb', 'mii_rs_customer_cluster', partition='predict_date')

    pass  # removed by ws4conv (K4-SPK-006): do not stop the shared session on Databricks


if __name__ == "__main__":
    main(sys.argv[1:])
